  RV.icon = function (name, opts) {
    opts = opts || {};
    var body = P[name] || P['circle'];
    var size = opts.size || 24;
    var sw = opts.stroke || 2;
    var a11y = opts.label
      ? ' role="img" aria-label="' + String(opts.label).replace(/"/g, '&quot;') + '"'
      : ' aria-hidden="true" focusable="false"';
    var cls = opts.cls ? ' class="' + opts.cls + '"' : '';
    return '<svg xmlns="http://www.w3.org/2000/svg" width="' + size + '" height="' + size + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="' + sw + '" stroke-linecap="round" stroke-linejoin="round"' + cls + a11y + '>' + body + '</svg>';
  };
